<script setup lang="ts">
import {API_BASE} from '@/lib/api-base'

import {computed,onMounted,onUnmounted,ref} from 'vue'
import {supabase} from '@/lib/supabase'
import {useAuthStore} from '@/stores/auth'
const auth=useAuthStore()
interface UserRow {assignments:any[];is_super_admin:boolean;id:string;full_name:string;email:string;role:string;department:string|null;job_title:string|null;active:boolean;organization_id:string|null;module_access:Record<string,boolean>;updated_at:string;session_version:number}
const teams=ref<any[]>([]),assignments=ref<any[]>([])
const users=ref<UserRow[]>([]),organizations=ref<{id:string;name:string}[]>([]),search=ref(''),company=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),show=ref(false),editing=ref<UserRow|null>(null)
const form=ref({full_name:'',email:'',role:'management',department:'',job_title:'',active:true,organization_id:'',module_access:{quality:true,strategy:false,lifecycle:false},password:'',confirm:''})
const modules=[{key:'quality',label:'Qualidade'},{key:'strategy',label:'Estratégia'},{key:'lifecycle',label:'LifeCycle RH'}] as const
const roles=computed(()=>[{value:'quality',label:'Gestor — editar e gerir'},{value:'management',label:'Direção — consulta'},{value:'action_owner',label:'Responsável por ações'},...(auth.isGlobalAdmin?[{value:'admin',label:'Administrador de empresa'}]:[])] )
async function request(path='',method='GET',body?:unknown){const {data:{session}}=await supabase.auth.getSession();if(!session)throw new Error('Inicia sessão novamente.');const res=await fetch(`${API_BASE}/auth/v1/admin/users${path}`,{method,headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const data=await res.json();if(!res.ok)throw new Error(data.msg||'Não foi possível concluir a operação.');return data}
async function load(){loading.value=true;error.value='';try{const [data,orgs]=await Promise.all([request(),supabase.from('organizations').select('id,name').eq('active',true).order('name')]);if(orgs.error)throw orgs.error;users.value=data;organizations.value=orgs.data??[];const t=await supabase.from('teams').select('*').order('name');teams.value=t.data||[]}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function refreshTeams(){const r=await supabase.from('teams').select('*').order('name');if(!r.error)teams.value=r.data||[]}
onMounted(()=>{void load();window.addEventListener('focus',refreshTeams)})
onUnmounted(()=>window.removeEventListener('focus',refreshTeams))
const filtered=computed(()=>users.value.filter(u=>(!company.value||u.organization_id===company.value)&&(u.full_name+' '+u.email).toLocaleLowerCase().includes(search.value.toLocaleLowerCase())))
function open(user:UserRow|null=null){editing.value=user;assignments.value=JSON.parse(JSON.stringify(user?.assignments||[])).map((a:any)=>({...a,starts_on:a.starts_on?.slice(0,10)||'',ends_on:a.ends_on?.slice(0,10)||''}));form.value={full_name:user?.full_name??'',email:user?.email??'',role:user?.role??'management',department:user?.department??'',job_title:user?.job_title??'',active:user?.active??true,organization_id:user?.organization_id??(auth.isGlobalAdmin?company.value:auth.profile?.organization_id??''),module_access:{quality:user?.module_access?.quality??true,strategy:user?.module_access?.strategy??false,lifecycle:user?.module_access?.lifecycle??false},password:'',confirm:''};error.value='';success.value='';show.value=true}
async function save(){error.value='';if(form.value.password!==form.value.confirm){error.value='As senhas não coincidem.';return}if((!editing.value||form.value.password)&&form.value.password.length<8){error.value='A senha deve ter pelo menos 8 caracteres.';return}saving.value=true;try{const {confirm,...data}=form.value;await request(editing.value?'/'+editing.value.id:'',editing.value?'PATCH':'POST',{...data,assignments:assignments.value.map(a=>({...a,starts_on:a.starts_on||null,ends_on:a.ends_on||null})),organization_id:data.organization_id||null,expected_updated_at:editing.value?.updated_at,expected_version:editing.value?.session_version});show.value=false;form.value.password='';form.value.confirm='';success.value='Utilizador guardado. As alterações aos acessos exigem novo início de sessão.';if(editing.value?.id===auth.profile?.id){await auth.signOut();location.assign('/login');return}await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function addAssignment(kind:string){assignments.value.push(kind==='team'?{kind,team_id:'',function_name:'',active:true,starts_on:'',ends_on:''}:{kind,module:'quality',role:'action_owner',active:true,starts_on:'',ends_on:''})}
function removeAssignment(a:any){if(a.used_at){a.active=false;a.ends_on=new Date().toLocaleDateString('sv-SE')}else assignments.value=assignments.value.filter(x=>x!==a)}
async function removeUser(){if(!editing.value||!confirm('Eliminar definitivamente este utilizador, apenas se nunca foi utilizado?'))return;try{await request('/'+editing.value.id,'DELETE',{confirm_delete:true});show.value=false;await load();success.value='Utilizador sem utilização eliminado. O registo administrativo foi preservado.'}catch(e){error.value=(e as Error).message}}
</script>
<template><section aria-label="Gestão de utilizadores">
 <div class="d-flex flex-wrap justify-content-between gap-3 mb-3"><p class="sq-muted mb-0">Cada utilizador pertence a uma empresa. Os administradores gerem a sua empresa; o superadministrador tem acesso global.</p><button class="btn btn-primary" :disabled="loading" @click="open()">Novo utilizador</button></div>
 <div v-if="error&&!show" class="alert alert-danger" role="alert">{{error}}</div><div v-if="success" class="alert alert-success" role="status">{{success}}</div>
 <div class="row g-3 mb-3"><div class="col-md-6"><label for="users-search" class="form-label">Pesquisar nome ou email</label><input id="users-search" v-model="search" class="form-control"/></div><div class="col-md-6"><label for="users-company" class="form-label">Empresa</label><select id="users-company" v-model="company" class="form-select"><option value="">{{auth.isGlobalAdmin?'Todas as empresas':'A minha empresa'}}</option><option v-for="o in organizations" :key="o.id" :value="o.id">{{o.name}}</option></select></div></div>
 <div class="table-responsive"><table class="sq-table"><thead><tr><th>Nome / Email</th><th>Empresa</th><th>Perfil</th><th>Módulos</th><th>Estado</th><th></th></tr></thead><tbody><tr v-if="loading"><td colspan="6">A carregar…</td></tr><tr v-for="u in filtered" v-else :key="u.id"><td>{{u.full_name}}<small class="d-block sq-muted">{{u.email}}</small></td><td>{{u.is_super_admin?'Todas':organizations.find(o=>o.id===u.organization_id)?.name||'Sem empresa'}}</td><td>{{u.is_super_admin?'Superadministrador':u.role==='admin'?'Administrador de empresa':u.assignments?.filter(a=>a.kind==='permission'&&a.active).map(a=>(roles.find(r=>r.value===a.role)?.label||a.role)+' ('+(modules.find(m=>m.key===a.module)?.label||a.module)+')').join(', ')||'Sem responsabilidades ativas'}}</td><td>{{u.role==='admin'?'Todos':modules.filter(m=>u.module_access?.[m.key]).map(m=>m.label).join(', ')||'Sem módulos'}}</td><td>{{u.active?'Ativo':'Inativo'}}</td><td><button class="btn btn-sm btn-outline-primary" :disabled="!auth.isGlobalAdmin && u.role==='admin'" @click="open(u)">Editar</button></td></tr></tbody></table></div>
 <div v-if="show" class="modal d-block" role="dialog" aria-modal="true" aria-labelledby="user-editor-title" style="background:rgba(0,0,0,.45)"><div class="modal-dialog modal-lg modal-dialog-scrollable"><form class="modal-content" @submit.prevent="save"><div class="modal-header"><h2 id="user-editor-title" class="h5 mb-0">{{editing?'Editar utilizador':'Novo utilizador'}}</h2><button type="button" class="btn-close" aria-label="Fechar" :disabled="saving" @click="show=false"></button></div><div class="modal-body"><div v-if="error" class="alert alert-danger" role="alert">{{error}}</div><fieldset :disabled="saving"><div class="row g-3">
 <div class="col-md-6"><label for="user-name" class="form-label">Nome</label><input id="user-name" v-model="form.full_name" required maxlength="200" class="form-control"/></div>
 <div class="col-md-6"><label for="user-email" class="form-label">Email</label><input id="user-email" v-model="form.email" :disabled="editing?.is_super_admin" required type="email" maxlength="254" class="form-control"/></div>
 <div class="col-md-6"><label for="user-role" class="form-label">Administração da empresa</label><select id="user-role" v-model="form.role" :disabled="editing?.is_super_admin" class="form-select"><option value="management">Utilizador com perfis atribuídos abaixo</option><option v-if="form.role==='quality'" value="quality">Utilizador com perfis atribuídos abaixo</option><option v-if="form.role==='action_owner'" value="action_owner">Utilizador com perfis atribuídos abaixo</option><option v-if="auth.isGlobalAdmin" value="admin">Administrador de empresa</option></select></div>
 <div class="col-md-6"><label for="user-organization" class="form-label">Empresa</label><select id="user-organization" v-model="form.organization_id" :required="!editing?.is_super_admin" :disabled="!auth.isGlobalAdmin||editing?.is_super_admin" class="form-select"><option value="">{{editing?.is_super_admin?'Acesso global':'Selecionar empresa…'}}</option><option v-for="o in organizations" :key="o.id" :value="o.id">{{o.name}}</option></select></div>
 <div class="col-12"><p v-if="form.department||form.job_title" class="sq-muted">Enquadramento anterior preservado: {{form.department}} · {{form.job_title}}</p><h3 class="h6">Equipas / Departamentos / Funções</h3><p class="small">Usa a mesma conta para adicionar várias equipas e funções. Terminar uma atribuição mantém as restantes. As funções na estrutura não concedem, por si só, permissões na aplicação.</p><div v-for="(a,i) in assignments.filter(a=>a.kind==='team')" :key="a.id||i" class="border rounded p-2 mb-2"><div class="row g-2"><div class="col-md-5"><label class="form-label">Equipa ou departamento<select v-model="a.team_id" class="form-select" :disabled="!!a.used_at"><option value="">Selecionar…</option><option v-for="t in teams.filter(t=>t.organization_id===form.organization_id&&(t.active||t.id===a.team_id))" :key="t.id" :value="t.id">{{t.name}}</option></select></label></div><div class="col-md-5"><label class="form-label">Função nesta unidade<input v-model="a.function_name" class="form-control" :disabled="!!a.used_at"/></label></div><div class="col-md-2"><button type="button" class="btn btn-sm btn-outline-secondary" @click="removeAssignment(a)">{{a.used_at?'Terminar':'Remover'}}</button></div></div><div class="row g-2"><div class="col"><label>Início<PtDateInput v-model="a.starts_on" class="form-control"/></label></div><div class="col"><label>Fim<PtDateInput v-model="a.ends_on" class="form-control"/></label></div><div class="col"><label><input v-model="a.active" type="checkbox"/> Atribuição ativa</label></div></div></div><button type="button" class="btn btn-outline-primary" @click="addAssignment('team')">Adicionar equipa ou função</button><RouterLink to="/administracao/organizacoes" target="_blank" class="ms-3">Gerir equipas</RouterLink></div>
 <div class="col-12"><h3 class="h6">Perfis / Responsabilidades</h3><p class="small">As permissões dos perfis ativos acumulam-se dentro de cada módulo. Sem acesso ao módulo, os perfis não permitem entrar. Terminar um perfil mantém os restantes.</p><div v-for="(a,i) in assignments.filter(a=>a.kind==='permission')" :key="a.id||i" class="row g-2 border rounded p-2 mb-2"><div class="col-md-4"><label>Módulo<select v-model="a.module" class="form-select" :disabled="!!a.used_at"><option v-for="m in modules" :key="m.key" :value="m.key">{{m.label}}</option></select></label></div><div class="col-md-4"><label>Perfil<select v-model="a.role" class="form-select" :disabled="!!a.used_at"><option v-for="role in roles.filter(r=>r.value!=='admin')" :key="role.value" :value="role.value">{{role.label}}</option></select></label></div><div class="col-md-4"><label><input v-model="a.active" type="checkbox"/> Perfil ativo</label><button type="button" class="btn btn-sm btn-outline-secondary ms-2" @click="removeAssignment(a)">{{a.used_at?'Terminar':'Remover'}}</button></div></div><button type="button" class="btn btn-outline-primary" @click="addAssignment('permission')">Adicionar perfil</button></div>
 <div class="col-12"><label class="form-check"><input v-model="form.active" :disabled="editing?.is_super_admin" type="checkbox" class="form-check-input"/>Utilizador ativo</label></div>
 <div class="col-12"><h3 class="h6">Acesso aos módulos</h3><p v-if="form.role==='admin'" class="sq-muted">Os administradores têm acesso aos três módulos dentro do seu âmbito: empresa ou acesso global.</p><div class="d-flex flex-wrap gap-4"><label v-for="m in modules" :key="m.key" class="form-check"><input type="checkbox" class="form-check-input" :checked="form.role==='admin'||form.module_access[m.key]" :disabled="form.role==='admin'" @change="form.module_access[m.key]=($event.target as HTMLInputElement).checked"/>{{m.label}}</label></div><small class="sq-muted">O perfil determina as operações permitidas dentro de cada módulo.</small></div>
 <div class="col-12"><h3 class="h6 mt-2">{{editing?'Redefinir senha':'Senha inicial'}}</h3><p v-if="editing" class="sq-muted mb-1">Deixa em branco para manter a senha atual. As senhas existentes nunca são mostradas.</p></div>
 <div class="col-md-6"><label for="user-password" class="form-label">Nova senha</label><input id="user-password" v-model="form.password" type="password" autocomplete="new-password" :required="!editing" minlength="8" maxlength="256" class="form-control"/></div><div class="col-md-6"><label for="user-confirm" class="form-label">Confirmar senha</label><input id="user-confirm" v-model="form.confirm" type="password" autocomplete="new-password" :required="!!form.password" class="form-control"/></div>
 </div></fieldset></div><div class="modal-footer"><button v-if="editing&&!editing.is_super_admin&&editing.id!==auth.profile?.id" type="button" class="btn btn-outline-danger me-auto" :disabled="saving" @click="removeUser">Eliminar utilizador sem utilização</button><button type="button" class="btn btn-secondary" :disabled="saving" @click="show=false">Cancelar</button><button class="btn btn-primary" :disabled="saving">{{saving?'A guardar…':'Guardar'}}</button></div></form></div></div>
</section></template>
